public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the starting and ending n-tersections are valid
    if (start.length != n || end.length != n) {
        return "cannot be travelled";
    }

    // Check if the paths are valid
    for (int i = 0; i < paths.length; i++) {
        if (paths[i].length != n) {
            return "cannot be travelled";
        }
    }

    // Initialize a boolean array to keep track of visited n-tersections
    boolean[] visited = new boolean[n];

    // Initialize a queue to perform BFS
    Queue<int[]> queue = new LinkedList<>();

    // Add the starting n-tersection to the queue
    queue.add(start);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current n-tersection from the queue
        int[] current = queue.poll();

        // Check if the current n-tersection is the ending n-tersection
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }

        // Mark the current n-tersection as visited
        visited[current[0]] = true;

        // Loop through all the adjacent n-tersections
        for (int i = 0; i < paths.length; i++) {
            // Check if the adjacent n-tersection is not visited and is not the starting n-tersection
            if (!visited[paths[i][0]] && !Arrays.equals(paths[i], start)) {
                // Add the adjacent n-tersection to the queue
                queue.add(paths[i]);
            }
        }
    }

    // If the queue is empty and the ending n-tersection is not visited, return "cannot be travelled"
    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    int commonLetters = 0;
    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                commonLetters++;
                break;
            }
        }
    }
    int denominator = word1.length() + word2.length();
    if (denominator == 0) {
        return "0";
    }
    int numerator = commonLetters;
    int gcd = gcd(numerator, denominator);
    numerator /= gcd;
    denominator /= gcd;
    return numerator + "/" + denominator;
}

