    // Step 3: Iterate over the characters in the string
    for (int i = 0; i < s.length(); i++) {
        // Step 3.1: Get the substring starting from the current character
        String substring = s.substring(i);

        // Step 3.2: Check if the substring is unique
        if (!uniqueSubstrings.contains(substring)) {
            // Step 3.3: If the substring is unique, add it to the set of unique substrings
            uniqueSubstrings.add(substring);

            // Step 3.4: Update the maximum number of unique substrings
